formal_property.sva:
// Check that a rising edge on event_rx_break_err leads to interrupt assertion, and no glitch re-triggers while event stays high.
assert property (@(posedge clk_i) disable iff (!rst_ni)
  ($rose(event_rx_break_err) |-> intr_rx_break_err_o) and
  (event_rx_break_err && $past(intr_rx_break_err_o) |-> $stable(intr_rx_break_err_o)));

