formal_property.sva:
property p_glitch_sreg_clear;
  @(posedge clk_i) disable iff (!rst_ni)
  (rx_enable && !idle_q && tick_baud_q && (bit_cnt_q == (parity_enable ? 4'd11 : 4'd10)) && rx)
  |=> (sreg_q == '0);
endproperty
assert property (p_glitch_sreg_clear);

